def bubble_sort(arr):
    n = len(arr)
    passes = 0
    for i in range(n - 1):
        swapped = False
        passes += 1
        for j in range(n - 1 - i):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
        if not swapped:
            break
    return passes

def count_occ(s, ch):
    if s == "":
        return 0
    return (1 if s[0] == ch else 0) + count_occ(s[1:], ch)

